// Minimal API
app.MapGet("/orders/{id}", async (int id, HttpContext ctx, IAuthorizationService authz, OrdersDb db) =>
{
    var order = await db.Orders.FindAsync(id);
    if (order is null) return Results.NotFound();

    var result = await authz.AuthorizeAsync(ctx.User, order, "CanEditOrder");
    if (!result.Succeeded) return Results.Forbid();

    return Results.Ok(order);
}).RequireAuthorization("CanEditOrder");

public class AllowAllOrdersHandler : IAuthorizationHandler
{
    public Task HandleAsync(AuthorizationHandlerContext context)
    {
        foreach (var r in context.Requirements)
            context.Succeed(r);
        return Task.CompletedTask;
    }
}

